import{_ as t,o as s,c as a,a4 as o}from"./chunks/framework.kn7HWrZO.js";const m=JSON.parse('{"title":"DeepSeek Harness Architecture","description":"","frontmatter":{"editSource":"docs/architecture.md","rawMarkdownPath":"en/reference/index.md"},"headers":[],"relativePath":"en/reference/index.md","filePath":"en/reference/index.md"}'),n={name:"en/reference/index.md"};function r(d,e,i,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="deepseek-harness-architecture" tabindex="-1">DeepSeek Harness Architecture <a class="header-anchor" href="#deepseek-harness-architecture" aria-label="Permalink to &quot;DeepSeek Harness Architecture&quot;">​</a></h1><p>Read this before changing anything under <code>packages/</code>. It assumes you know Cordis; if you do not, start with the <a href="./cordis-primer">primer</a> or the <a href="./../develop/cordis-tutorial/">tutorial</a>.</p><h2 id="cordis" tabindex="-1">Cordis <a class="header-anchor" href="#cordis" aria-label="Permalink to &quot;Cordis&quot;">​</a></h2><p><a href="./cordis-primer">Cordis</a> is the framework under dsh: plugins contribute services, typed events, and reversible effects to a shared context. Every part of the product is a plugin, including the model adapter, the tool registry, the session log, and the agent loop itself, so each is replaceable from configuration.</p><p>There is no privileged core to patch: you extend dsh by mounting a plugin beside the others, and registrations are effects that unwind when their plugin unloads.</p><h2 id="profiles-and-bundles" tabindex="-1">Profiles and bundles <a class="header-anchor" href="#profiles-and-bundles" aria-label="Permalink to &quot;Profiles and bundles&quot;">​</a></h2><p>A running <code>dsh</code> is a plugin tree composed at boot from ordered layers.</p><p>A <strong>profile</strong> is a named composition stored in the Harness home. It lists the bundles it stacks, holds any out-of-tree plugins it installs, and keeps the user&#39;s own <code>cordis.patch.yml</code>. <code>web</code>, <code>headless</code>, <code>sdk</code>, <code>sdk-minimal</code>, and <code>acp</code> ship as templates.</p><p>A <strong>bundle</strong> is a distribution format for Cordis config rows and the code they mount, so whatever it inserts stays patchable by the layers above it.</p><p>Each declares itself in its own <code>package.json</code> under a <code>dsh</code> field: <code>dsh.profile</code> lists a profile&#39;s bundles, and <code>dsh.bundle</code> points at a bundle&#39;s patch file.</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/base/README.md" target="_blank" rel="noreferrer"><code>dsh-base</code></a> is the shared first layer of the <code>web</code>, <code>headless</code>, <code>sdk</code>, and <code>acp</code> profiles: model adapters, tools, persistence, sandbox and approval policy, settings, credentials, telemetry. <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/web-app/README.md" target="_blank" rel="noreferrer"><code>dsh-web-app</code></a> adds the browser application, <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/headless/README.md" target="_blank" rel="noreferrer"><code>dsh-headless</code></a> adds a one-shot runner with no server, <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/sdk-app/README.md" target="_blank" rel="noreferrer"><code>dsh-sdk-app</code></a> adds the SDK JSON-RPC server, and <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/acp-app/README.md" target="_blank" rel="noreferrer"><code>dsh-acp-app</code></a> adds the automation-only ACP server. <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/sdk-minimal/README.md" target="_blank" rel="noreferrer"><code>dsh-sdk-minimal</code></a> is the deliberate exception: one bundle owns its complete explicit SDK tree and does not apply <code>dsh-base</code>.</p><p>Layers apply to an empty entry list: the profile&#39;s ordered bundles, its <code>cordis.patch.yml</code>, the home patch, then <code>--patch</code> overlays. A patch targets a row by id and replaces its whole config, or inserts new rows. A <code>preset</code> patch applies these operations inside that declaration’s <code>config.plugins</code>, with the same layer precedence.</p><p>YAML controls HMR: base enables config-only <code>dsh-hmr</code>; headless, SDK and ACP disable it; <code>sdk-minimal</code> omits it. Profile patches override these defaults. HMR coordinates watching and reloads; the launcher provides profile data and readiness.</p><p>Base includes <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/boot/plugin-manager/README.md" target="_blank" rel="noreferrer">Plugin Manager</a> for Web and agents.</p><p>To see the tree your machine boots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre></div><p>Any row it prints can be replaced by a patch of your own.</p><p>Composition mechanics are in <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/boot/app-boot/README.md#profiles" target="_blank" rel="noreferrer">app-boot</a>; config fields are in the generated <a href="./config-catalog">config catalog</a>.</p><h2 id="application-launch" tabindex="-1">Application launch <a class="header-anchor" href="#application-launch" aria-label="Permalink to &quot;Application launch&quot;">​</a></h2><p>Supported Node applications launch through named <code>dsh</code> profiles. The shipped profiles are <code>web</code>, <code>headless</code>, <code>sdk</code>, <code>sdk-minimal</code>, and <code>acp</code>, selected with <code>dsh --profile &lt;name&gt;</code> or <code>dsh &lt;name&gt;</code>. <code>plugin</code> names the management command; a profile with that name requires <code>--profile plugin</code>. The TypeScript SDK resolves its same-version <code>dsh</code> dependency and selects <code>sdk</code>; custom plugin composition remains a profile plus ordered patch files, not another executable or inline application tree. <code>sdk-minimal</code> is a repository-owned standalone bundle behind the same launcher, not a caller-supplied Cordis tree.</p><p>Vendored CLIs, build-only and test-only executables, direct in-process plugin mounting, and the private browser WebWorker preview are not Harness application launchers. <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/verify-application-entrypoints.ts" target="_blank" rel="noreferrer"><code>verify-application-entrypoints</code></a> keeps every package bin, executable source, root demo, and the root <code>start:web</code> and <code>dev:web</code> scripts in an explicit class and rejects a Node application path that bypasses <code>dsh</code>.</p><p>The Python SDK follows the same application architecture. Its runtime wheel packages the normal <code>dsh</code> CLI as <code>deepseek-harness-sdk-runtime-&lt;platform&gt;-&lt;arch&gt;</code>, and the client launches <code>dsh --profile sdk</code> with an explicit Harness home by default. The minimal example selects the shipped <code>sdk-minimal</code> profile. Python exposes profile selection and ordered patch files rather than a complete Cordis tree; persistent external plugins are installed through <code>dsh plugin</code>. The removed private direct-config carrier has no compatibility bin or fallback parser.</p><h2 id="desktop-application" tabindex="-1">Desktop application <a class="header-anchor" href="#desktop-application" aria-label="Permalink to &quot;Desktop application&quot;">​</a></h2><p>The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/README.md" target="_blank" rel="noreferrer">Electron desktop application</a> ships its exact dsh production runtime in signed resources and owns the reserved <code>$DSH_HOME/profiles/desktop</code>. Shared helpers initialize profile files, reconcile bundles, and resolve installation and bundle dependencies without replacing pnpm-owned packages. Desktop and npm CLI share product data but keep packages, activation, and lockfiles separate. Desktop’s bundled CLI manages its initialized plugins.</p><p>Electron starts the private Desktop Host in Electron Node mode. The Host invokes the shared CLI profile runner and complete Web application. The window immediately loads packaged Web assets and waits for boot injections before activating client plugins in the same document. Web owns RPC and streams; the desktop carrier connects the local page to the authenticated Host. Node IPC carries boot injections, readiness, fatal errors, and shutdown. Desktop listens on an OS-assigned port by default; profile configuration can override it. Shell-owned UI runs plugin transactions through bundled pnpm with normal user and profile configuration.</p><h2 id="core-packages" tabindex="-1">Core packages <a class="header-anchor" href="#core-packages" aria-label="Permalink to &quot;Core packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Owns</th><th><code>ctx</code> key</th></tr></thead><tbody><tr><td><a href="./subsystems/session"><code>core/session</code></a></td><td>The append-only <code>SessionEvent</code> log and in-memory store</td><td><code>ctx.sessions</code></td></tr><tr><td><a href="./subsystems/system-prompt"><code>core/system-prompt</code></a></td><td>Prompt-section and tool-schema assembly</td><td><code>ctx.systemPrompt</code></td></tr><tr><td><a href="./subsystems/tools"><code>core/tools</code></a></td><td>The scoped tool registry and guarded execution pipeline</td><td><code>ctx.tools</code></td></tr><tr><td><a href="./subsystems/core"><code>core/agent</code></a></td><td>The <code>Agent</code> interface, live registry, and <code>agent/*</code> events</td><td><code>ctx.agents</code></td></tr><tr><td><a href="./subsystems/core"><code>core/agent-loop</code></a></td><td>The default driver implementing that interface</td><td><code>ctx.agentLoop</code></td></tr><tr><td><a href="./subsystems/scope"><code>core/scope</code></a></td><td>The per-agent scoped-registration primitive</td><td>library, no key</td></tr><tr><td><a href="./subsystems/llm-streaming"><code>llm/llm</code></a></td><td>Message and stream vocabulary plus the adapter seam</td><td><code>ctx.llm</code></td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>Events are the extension points, and picking the right domain is the first decision in most changes.</p><ul><li><strong>Session events</strong> are durable facts appended to the log and broadcast through <code>session/event</code>. Use one when the fact must survive a reload.</li><li><strong>Agent events</strong> (<code>agent/*</code>) carry a live <code>Agent</code>: inbox, step, status, request, validation, continuation. Use one to observe or intercept work in flight.</li><li><strong>Capability events</strong> attach policy and adapters to a seam (<code>fs/*</code>, <code>tools/*</code>, <code>telemetry/*</code>) without importing the loop.</li></ul><p>AgentLoop initializes Agents with rollback and awaits serial <code>agent/created</code> before queued work. Unload retains resources through Agent teardown; <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/core/agent-loop/README.md#understand-the-implementation" target="_blank" rel="noreferrer">agent-loop</a> defines ordering.</p><p>The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/event-producer-consumer.md" target="_blank" rel="noreferrer">event map</a> lists every event&#39;s producers and consumers.</p><h2 id="turn-flow" tabindex="-1">Turn flow <a class="header-anchor" href="#turn-flow" aria-label="Permalink to &quot;Turn flow&quot;">​</a></h2><p>A <strong>step</strong> is one model request plus the tools it calls. A <strong>turn</strong> is zero or more steps: it opens before its first input is claimed and closes once nothing is owed.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>turn/start</span></span>
<span class="line"><span>  claim next-step input plus one queued message</span></span>
<span class="line"><span>  snapshot Session model selection; assemble prompt sections + step-admitted tool schemas</span></span>
<span class="line"><span>  -&gt; agent/pre-step; project runtime context at fallback</span></span>
<span class="line"><span>                                     reject | enter(messages, startsRequestSeries?)</span></span>
<span class="line"><span>     reject, or a first enter rewritten empty -&gt; close the turn with no step</span></span>
<span class="line"><span>     step/start</span></span>
<span class="line"><span>     agent/request -&gt; prepareCall (cancellation commits neither system nor users)</span></span>
<span class="line"><span>     reconcile system/message using the prepared call capability</span></span>
<span class="line"><span>     append entered messages as user/message; reconcile retained runtime context</span></span>
<span class="line"><span>     log request/header and request/context as needed</span></span>
<span class="line"><span>     derive and freeze model history from the log</span></span>
<span class="line"><span>     stream the bound prepared call -&gt; llm/stream -&gt; agent/assistant-stream start</span></span>
<span class="line"><span>       agent/assistant-stream chunk*</span></span>
<span class="line"><span>       assistant/message | assistant/attempt -&gt; agent/assistant-stream end</span></span>
<span class="line"><span>     tool/call* -&gt; tools/pre-execute -&gt; tools/execute -&gt; tools/post-execute -&gt; tool/result*</span></span>
<span class="line"><span>     step/end</span></span>
<span class="line"><span>     tools owe another request, or next-step input arrived -&gt; claim -&gt; next step</span></span>
<span class="line"><span>  -&gt; agent/turn-stopping</span></span>
<span class="line"><span>turn/end</span></span></code></pre></div><p><code>turn/*</code>, <code>step/*</code>, <code>system/message</code>, <code>user/message</code>, <code>assistant/message</code>, <code>assistant/attempt</code>, and <code>tool/*</code> are durable session events; the rest are live extension points across three domains. <code>agent/assistant-stream</code> publishes process-local start, transient chunk, and end frames. The loop commits the complete compact stream as one message or log-only attempt before a committed end frame, and the Web Session-follow adapter is the live event&#39;s only remote consumer. <code>agent/pre-step</code>, <code>agent/request</code>, <code>llm/stream</code>, and the three <code>tools/*</code> events are waterfalls, whose listeners must call <code>next()</code> to delegate; <code>agent/turn-stopping</code> is serial and has no <code>next()</code>.</p><p>Factory setup follows SessionStore entry and <code>session/created</code>, preceding <code>agent/created</code>; closing events commit before removal.</p><p>One inbox feeds the driver; injected context waits for a waking message. AgentLoop’s durable <code>inbox</code> projection exposes pending input without live Agents.</p><p>Before assembly, the loop snapshots Session model selection in <code>AssembleContext.modelSelection</code> and <code>agent/pre-step.modelSelection</code>; retries retain it; omitted reasoning effort uses adapter defaults. <code>agent/pre-step</code> listeners accept, rewrite, or reject claimed messages; a rejected or empty first claim closes a durable turn without a step. An enter decision may set <code>startsRequestSeries</code>: the loop logs a fresh <code>request/header</code> (reason <code>series</code>, or <code>change</code> with <code>startsSeries: true</code> when the envelope also changed). Wrapping listeners preserve that declaration with <code>{ ...decision, messages }</code>. After assembly and <code>step/start</code>, the deprecated <code>agent/request</code> hook adjusts controls without changing the provider, model, or effort selection, and <code>prepareCall()</code> binds the adapter before the system prompt and accepted users are committed; cancellation during either async phase commits neither. Prepared call capabilities govern prompt admission, not preceding <code>request/context</code>. Each attempt refreshes registered runtime facts, reconciles the bound prompt, admits users once, and restores removed runtime context, logs header/context as needed, and freezes the request before streaming the bound call. Retries do not repeat assembly or <code>agent/pre-step</code>. Surface replacements and image-offload decisions after attachment start a new request series, including during the first resumed pre-step; unchanged resume continues the series. The system prompt travels as <code>system/message</code> history: empty text clears it, capable routes append updates, and other routes consolidate it at the first system node. <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/core/agent-loop/README.md#understand-the-implementation" target="_blank" rel="noreferrer">Agent-loop</a> owns prompt admission and replacement details.</p><p>The loop sends immutable requests with live cancellation and reuses freeze evidence for frozen identities; <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/core/agent-loop/README.md" target="_blank" rel="noreferrer">agent-loop</a> owns construction and cancellation causes.</p><p>Failed steps <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/core/agent-loop/README.md#understand-the-implementation" target="_blank" rel="noreferrer">record missing tool results</a>.</p><p>Details: the <a href="./agent-lifecycle">sequence diagram</a>, the <a href="./tool-execution-pipeline">tool pipeline</a>, and <a href="./subsystems/core#the-agent-handle">cancellation and error recovery</a>.</p><p><a href="./subsystems/tools"><code>ctx.tools.execute()</code></a> receives raw batches and concurrency limits.</p><h2 id="session-log" tabindex="-1">Session log <a class="header-anchor" href="#session-log" aria-label="Permalink to &quot;Session log&quot;">​</a></h2><p>The session log is the source of the context the model sees. <code>deriveMessages()</code> projects model history from it. Each <code>assistant/message</code> embeds the exact compact timed stream that produced its assembled content; <code>assistant/attempt</code> retains settled failed, retried, cancelled, and stream-error attempts without adding model history. Fork, resume, transcripts, telemetry, and persistence all derive from these durable settlements, while live UI incrementality comes from <code>agent/assistant-stream</code>; a hard process loss before settlement leaves no durable attempt stream (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/architecture/2026-09-01-v2-embedded-assistant-streams.md" target="_blank" rel="noreferrer">decision</a>).</p><p>Session consumers know only the current logical format. Header-only <code>stat</code> and <code>list</code> rescan each Session directory, select its numerically highest canonical generation, and translate a supported historical header without loading events or publishing a successor. A stored-session <code>open</code> selects that same generation, refuses a future version, or decodes and composes the static adjacent migration chain once before returning validated current logical events. A read open uses that in-memory result without publishing a successor; a write open first encodes, verifies, and exclusively publishes the final version-named successor beside the unchanged source. Ordinary repair of an unsealed interrupted tail remains a handle consumer responsibility; migration inserts a missing interrupted <code>turn/end</code> only for the bounded released restart already sealed by a later <code>turn/start</code>. JSONL v0 uses <code>session.jsonl[.zstd]</code>, v1 and later use lowercase <code>session.vN.jsonl[.zstd]</code>, and committed generation paths are never renamed, replaced, or deleted. The JSONL provider owns physical framing, compression, generation selection, and exclusive publication, while each adjacent migration package owns exactly one <code>vN -&gt; vN+1</code> step (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/architecture/2026-08-31-released-session-format-migrations.md" target="_blank" rel="noreferrer">decision</a>).</p><p><strong>Model-visible means logged.</strong> Every model request must be reconstructable from the log. New model-visible inputs require session events. Plugins changing existing message content register <a href="./subsystems/session#plugin-owned-message-projections">pure message projections</a>; detached readers supply the same definitions explicitly. Tool changes are capability-independent; <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/core/session/README.md" target="_blank" rel="noreferrer">Session tool history</a> supplies provider declarations.</p><p><strong>Projection seam.</strong> <code>dsh-session-projection</code> owns <code>ctx.sessionProjections</code>: registered units fold committed events incrementally, and carriers batch cropped client views with <code>snapshot()</code>. Domain services await registration during activation, retain private handles, and expose business methods for other plugins. Releasing registration removes global participation; retained handles continue folding Session events. <code>AgentRegistry</code> owns turn and step state and exposes <code>turnBoundaryOf(session)</code> (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/session/session-projection/README.md" target="_blank" rel="noreferrer">registration lifecycle</a>). <code>AgentLoop</code> owns <code>modelSelection</code> and constructs each Agent’s <code>model</code> instance alongside its inbox.</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/subsystems/working-directory.md" target="_blank" rel="noreferrer">Working directories</a> supply user context and execution paths without changing original project identity, sandbox write roots, or existing process directories.</p><h2 id="capability-seams" tabindex="-1">Capability seams <a class="header-anchor" href="#capability-seams" aria-label="Permalink to &quot;Capability seams&quot;">​</a></h2><p>A <strong>seam</strong> is a swappable capability with three roles: a <strong>Service Definition</strong> declaring the interface, a <strong>Service Provider</strong> implementing it, and a <strong>Consumer</strong> using it, commonly a model-facing tool. A package may combine roles, but one role alone is not a seam; adding a capability means designing all three (<a href="./capability-seams">capability graph</a>).</p><p>Seams are why one provider swap changes the whole product. Filesystem and subprocess providers share one execution world, so pointing them at a remote sandbox moves Bash, PTY, and LSP with them, with no provider forks. <a href="./subsystems/subagent">Subagent providers</a> vary just as widely behind one interface, from a fresh child agent to a delegated turn in another product.</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/subsystems/agent-team.md" target="_blank" rel="noreferrer">Experimental Agent Teams</a> exposes opt-in <code>ctx.agentTeams</code> coordination with durable roster and task state plus direct inbox messaging over continuable subagents.</p><h2 id="where-new-behavior-goes" tabindex="-1">Where new behavior goes <a class="header-anchor" href="#where-new-behavior-goes" aria-label="Permalink to &quot;Where new behavior goes&quot;">​</a></h2><p>New behavior attaches to a documented extension point. Changing the loop itself updates this map.</p><table tabindex="0"><thead><tr><th>Goal</th><th>Mechanism</th></tr></thead><tbody><tr><td>Add a model provider</td><td>register its adapter on <code>ctx.llm</code></td></tr><tr><td>Add a model-facing capability</td><td>register on <code>ctx.tools</code>; its schema joins prompt assembly</td></tr><tr><td>Give one session a different capability set</td><td>compose an agent preset; a service row there needs an <code>isolate</code> realm</td></tr><tr><td>Add shell execution</td><td>register a <code>ctx.shell</code> backend; the local one spawns through <code>ctx.subprocess</code></td></tr><tr><td>Add persistent terminal execution</td><td>register a <code>ctx.terminals</code> backend plus <code>dsh-tool-terminal</code></td></tr><tr><td>Add a human command</td><td>register on <code>ctx.commands</code>; it dispatches without a model turn</td></tr><tr><td>Manage background jobs</td><td>register on <code>ctx.jobs</code>; <code>job_*</code> tools read or stop jobs</td></tr><tr><td>Start a Session from an external webhook</td><td>register a trusted rule on <code>ctx.webhookRuntime</code> and mount a provider adapter</td></tr><tr><td>Add filesystem access or policy</td><td>register a <code>ctx.fs</code> provider or listen to <code>fs/*</code> events</td></tr><tr><td>Confine spawned processes</td><td>use a <code>ctx.sandbox</code> backend; consumers wrap argv before spawning</td></tr><tr><td>Intercept a request, tool, or turn</td><td>use its <code>agent/*</code> or <code>tools/*</code> event; <code>agent/turn-stopping</code> stops a turn</td></tr><tr><td>Add model-facing context</td><td>call <code>agent.inject()</code>; it lands in the next admitted request</td></tr><tr><td>Add UI or editor integration</td><td>drive <code>ctx.agents</code> and render from <code>session/event</code></td></tr><tr><td>Add a Web Client Chat node</td><td>register a <code>ConversationNodeDefinition</code> + keyed renderer</td></tr><tr><td>Add durable session state</td><td>extend <code>SessionEventMap</code>; render and replay from the log</td></tr><tr><td>Generate session titles</td><td>register the sole <code>ctx.sessionTitle</code> provider</td></tr><tr><td>Manage a same-session objective</td><td>use <code>ctx.goals</code>; continue through <code>agent/*</code></td></tr><tr><td>Fork at a turn boundary</td><td><code>ctx.agents.create({ sessionId, seed, inheritedEventCount, meta: { isSeeded: true } })</code> — only agent-loop-published sessions persist</td></tr><tr><td>Store sessions in a new backend</td><td>implement <code>SessionPersistence</code> (<code>create</code>/<code>open</code>/<code>stat</code>/<code>list</code>/<code>export</code>) over the shared handle scaffolding</td></tr><tr><td>Scope a registration to one agent</td><td>use that agent&#39;s <code>agent.ctx</code></td></tr></tbody></table><p>The <a href="./cookbook/extension-cookbook">extension cookbook</a> maps features to capabilities and indexes the step-by-step guides for <a href="./cookbook/adding-a-package">packages</a>, <a href="./cookbook/adding-a-tool">tools</a>, <a href="./cookbook/adding-an-llm-adapter">LLM adapters</a>, and <a href="./cookbook/adding-a-settings-card">settings pages</a>. The <a href="./subsystems/conversation">Conversation subsystem</a> owns Chat-node assembly.</p>`,57)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
